defense.vulnerable_config:
# Finding GPOs with weak ACEs:
Get-DomainGPO | Get-DomainObjectAcl -ResolveGUIDs |
    Where-Object {
        $_.ActiveDirectoryRights -match 'CreateChild|WriteProperty|GenericAll' -and
        $_.IdentityReference -notmatch 'Domain Admins|SYSTEM|Enterprise Admins'
    } | Select-Object ObjectDN, IdentityReference, ActiveDirectoryRights
